export function build(manim) {
  const {Scene,Graph,Text,VGroup,Circle,Line,Create,FadeIn,FadeOut,Indicate,Transform,BLUE,TEAL,YELLOW,GRAY,WHITE}=manim;
  const scene=new Scene();
  const positions={a:[-4.8,1.6,0],b:[-4.3,-1.0,0],c:[-2.2,0.3,0],d:[0.2,1.5,0],e:[0.8,-1.1,0],f:[3.0,0.5,0],q:[5.0,1.1,0]};
  const nodes=["a","b","c","d","e","f","q"];
  const graph=Graph(nodes,[["a","c"],["b","c"],["c","d"],["c","e"],["d","f"],["e","f"],["f","q"]],{layout:positions,labels:false});
  const title=Text("一个结论，连接许多次探索",{color:WHITE}).scale(0.6).move_to([0,2.9,0]);
  scene.play(FadeIn(title),{run_time:1});
  for(const id of nodes) graph.get_vertex(id).set_color(id==="q"?YELLOW:BLUE);
  for(const id of ["a","b","c","d","e","f"]) scene.play(FadeIn(graph.get_vertex(id)),{run_time:0.45});
  scene.wait(1);
  for(const edge of [["a","c"],["b","c"],["c","d"],["c","e"],["d","f"],["e","f"]]) scene.play(Create(graph.get_edge(edge[0],edge[1])),{run_time:0.5});
  const method=Text("方法",{color:BLUE}).scale(0.5).move_to([-3.8,-2.3,0]);
  const evidence=Text("证据",{color:TEAL}).scale(0.5).move_to([0,-2.3,0]);
  const question=Text("新问题",{color:YELLOW}).scale(0.5).move_to([3.8,-2.3,0]);
  scene.play(FadeIn(method),FadeIn(evidence),{run_time:1});
  scene.play(FadeIn(graph.get_vertex("q")),Create(graph.get_edge("f","q")),FadeIn(question),{run_time:1.5});
  scene.play(Indicate(graph.get_vertex("q")),{run_time:1});
  scene.wait(0.5);
  return scene;
}

export function build(manim) {
  const {Scene,Text,SurroundingRectangle,VGroup,Arrow,Create,FadeIn,FadeOut,Transform,Indicate,BLUE,TEAL,YELLOW,GRAY,WHITE}=manim;
  const scene=new Scene();
  const a=Text("论文 A",{color:BLUE}).scale(0.7).move_to([-3.8,0.5,0]);
  const b=Text("论文 B",{color:TEAL}).scale(0.7).move_to([3.8,0.5,0]);
  const ba=SurroundingRectangle(a,{buff:0.45,color:BLUE});
  const bb=SurroundingRectangle(b,{buff:0.45,color:TEAL});
  const link=Arrow(ba.get_right(),bb.get_left(),{color:GRAY,buff:0.2});
  const label=Text("引用",{color:WHITE}).scale(0.5).move_to([0,1.1,0]);
  scene.play(FadeIn(a),Create(ba),FadeIn(b),Create(bb),{run_time:1.5});
  scene.play(Create(link),FadeIn(label),{run_time:1.5});
  scene.wait(1);
  const h=Text("继承？   验证？   反驳？",{color:YELLOW}).scale(0.55).move_to([0,-1.2,0]);
  scene.play(FadeIn(h),{run_time:1.5});
  scene.play(Indicate(link),{run_time:1});
  const full=Text("阅读全文中的引用语境",{color:TEAL}).scale(0.55).move_to([0,-2.5,0]);
  scene.play(FadeIn(full),{run_time:1.5});
  scene.wait(0.5);
  return scene;
}

export function build(manim) {
  const {Scene,Graph,Text,Line,Create,FadeIn,FadeOut,Indicate,BLUE,TEAL,YELLOW,GRAY,WHITE}=manim;
  const scene=new Scene();
  const pos={a:[-5,1.5,0],b:[-5,-0.6,0],c:[-2.8,0.5,0],s:[-0.5,0.5,0],d:[1.7,1.5,0],e:[1.7,-0.6,0],n:[4.2,0.5,0],x:[-3.7,-2.0,0],f:[4.0,2.3,0],r:[5.4,-1.5,0]};
  const edges=[["a","c"],["b","c"],["c","s"],["s","d"],["s","e"],["d","n"],["e","n"],["b","x"]];
  const g=Graph(Object.keys(pos),edges,{layout:pos,labels:false});
  for(const id of Object.keys(pos))g.get_vertex(id).set_color(id==="x"?GRAY:id==="f"||id==="r"?YELLOW:BLUE);
  for(const p of edges)g.get_edge(p[0],p[1]).set_stroke(GRAY,2);
  const seed=Text("种子论文",{color:WHITE}).scale(0.45).move_to([-0.5,-0.3,0]);
  scene.play(FadeIn(g.get_vertex("s")),FadeIn(seed),{run_time:1});
  for(const id of ["c","a","b","d","e","n","x"])scene.play(FadeIn(g.get_vertex(id)),{run_time:0.3});
  for(const p of edges)scene.play(Create(g.get_edge(p[0],p[1])),{run_time:0.25});
  scene.wait(0.7);
  const relevant=Text("相关性过滤",{color:TEAL}).scale(0.5).move_to([-3.7,-2.8,0]);
  scene.play(FadeIn(relevant),FadeOut(g.get_vertex("x")),FadeOut(g.get_edge("b","x")),{run_time:1.5});
  const spine=[["a","c"],["c","s"],["s","d"],["d","n"]];
  scene.play(...spine.map(p=>g.get_edge(p[0],p[1]).animate.set_stroke(TEAL,5)),{run_time:1.5});
  const backbone=Text("优先阅读的历史主干",{color:TEAL}).scale(0.45).move_to([0,2.9,0]);
  scene.play(FadeIn(backbone),{run_time:1});
  scene.play(FadeIn(g.get_vertex("f")),FadeIn(g.get_vertex("r")),{run_time:1.5});
  const frontier=Text("按主题寻找近期工作",{color:YELLOW}).scale(0.4).move_to([3.3,-2.8,0]);
  scene.play(FadeIn(frontier),Indicate(g.get_vertex("f")),{run_time:1});
  scene.wait(0.5);
  return scene;
}

export function build(manim) {
  const {Scene,Axes,Text,Dot,DashedLine,Create,FadeIn,Indicate,BLUE,YELLOW,GRAY,TEAL,WHITE}=manim;
  const scene=new Scene();
  const re=Axes({x_range:[0,2,0.5],y_range:[-1.8,1.8,1],x_length:4.5,y_length:3.6}).move_to([-3.1,0,0]);
  const im=Axes({x_range:[0,2,0.5],y_range:[-1.8,1.8,1],x_length:4.5,y_length:3.6}).move_to([3.1,0,0]);
  const rt=Text("本征值的实部",{color:WHITE}).scale(0.5).move_to([-3.1,2.7,0]);
  const it=Text("本征值的虚部",{color:WHITE}).scale(0.5).move_to([3.1,2.7,0]);
  const zero=Text("教学示例 · γ = 1",{color:GRAY}).scale(0.4).move_to([0,-2.9,0]);
  scene.play(Create(re),Create(im),FadeIn(rt),FadeIn(it),FadeIn(zero),{run_time:1.5});
  const rp=re.plot(x=>Math.sqrt(Math.max(0,x*x-1)),{x_range:[1,2],color:BLUE});
  const rm=re.plot(x=>-Math.sqrt(Math.max(0,x*x-1)),{x_range:[1,2],color:YELLOW});
  const ip=im.plot(x=>Math.sqrt(Math.max(0,1-x*x)),{x_range:[0,1],color:BLUE});
  const ink=im.plot(x=>-Math.sqrt(Math.max(0,1-x*x)),{x_range:[0,1],color:YELLOW});
  scene.play(Create(rp),Create(rm),Create(ip),Create(ink),{run_time:2});
  const er=DashedLine(re.c2p(1,-1.7),re.c2p(1,1.7),{color:TEAL});
  const ei=DashedLine(im.c2p(1,-1.7),im.c2p(1,1.7),{color:TEAL});
  const ep=Text("g = 1 · 简并点",{color:TEAL}).scale(0.45).move_to([0,3.35,0]);
  scene.play(Create(er),Create(ei),FadeIn(ep),{run_time:1});
  const p1=Dot(re.c2p(0.15,0),{color:BLUE});
  const p2=Dot(re.c2p(0.15,0),{color:YELLOW});
  const q1=Dot(im.c2p(0.15,Math.sqrt(1-0.15*0.15)),{color:BLUE});
  const q2=Dot(im.c2p(0.15,-Math.sqrt(1-0.15*0.15)),{color:YELLOW});
  scene.play(FadeIn(p1),FadeIn(p2),FadeIn(q1),FadeIn(q2),{run_time:0.5});
  for(const x of [0.35,0.65,0.9,1,1.15,1.45,1.8]){
    const a=Math.sqrt(Math.max(0,x*x-1));
    const b=Math.sqrt(Math.max(0,1-x*x));
    scene.play(p1.animate.move_to(re.c2p(x,a)),p2.animate.move_to(re.c2p(x,-a)),q1.animate.move_to(im.c2p(x,b)),q2.animate.move_to(im.c2p(x,-b)),{run_time:0.7});
  }
  scene.wait(0.5);
  return scene;
}

export function build(manim) {
  const {Scene,Text,SurroundingRectangle,VGroup,Arrow,Line,Create,FadeIn,Indicate,BLUE,TEAL,YELLOW,WHITE,GRAY}=manim;
  const scene=new Scene();
  const names=["模型","参数与环境","运行记录","检查结果"];
  const colors=[BLUE,BLUE,TEAL,TEAL];
  const xs=[-4.65,-1.55,1.55,4.65];
  const blocks=names.map((s,i)=>{
    const t=Text(s,{color:colors[i]}).scale(0.5).move_to([xs[i],0.9,0]);
    return VGroup(SurroundingRectangle(t,{buff:0.32,color:colors[i]}),t);
  });
  for(let i=0;i<4;i++){
    scene.play(FadeIn(blocks[i]),{run_time:0.7});
    if(i>0)scene.play(Create(Arrow(blocks[i-1].get_right(),blocks[i].get_left(),{color:GRAY,buff:0.12})),{run_time:0.5});
  }
  scene.wait(0.8);
  const claim=Text("结论 + 适用范围",{color:YELLOW}).scale(0.6).move_to([2,-1.3,0]);
  const border=SurroundingRectangle(claim,{buff:0.35,color:YELLOW});
  const trace=Arrow(blocks[3].get_bottom(),border.get_top(),{color:TEAL,buff:0.15});
  scene.play(FadeIn(claim),Create(border),Create(trace),{run_time:1.5});
  const review=Text("解析极限 · 独立方法 · 收敛检查",{color:TEAL}).scale(0.45).move_to([-1.5,-2.8,0]);
  scene.play(FadeIn(review),{run_time:1.5});
  scene.play(Indicate(blocks[3]),{run_time:1});
  scene.wait(0.5);
  return scene;
}

export function build(manim) {
  const {Scene,Text,SurroundingRectangle,VGroup,Arrow,Cross,Create,FadeIn,FadeOut,Indicate,Transform,BLUE,TEAL,YELLOW,RED,GRAY,WHITE}=manim;
  const scene=new Scene();
  const bad=Text("错误候选：根号内相加",{color:RED}).scale(0.5).move_to([-3.2,1.5,0]);
  const good=Text("矩阵直接求本征值",{color:TEAL}).scale(0.5).move_to([3.2,1.5,0]);
  const b1=SurroundingRectangle(bad,{buff:0.4,color:RED});
  const b2=SurroundingRectangle(good,{buff:0.4,color:TEAL});
  scene.play(FadeIn(bad),Create(b1),FadeIn(good),Create(b2),{run_time:1.5});
  const mismatch=Text("g = 1 时，预测不一致",{color:RED}).scale(0.55).move_to([0,-0.15,0]);
  scene.play(FadeIn(mismatch),{run_time:1.5});
  scene.play(Create(Cross(b1,{stroke_color:RED})),{run_time:1});
  scene.wait(0.8);
  const lesson=Text("此模型：复核行列式符号",{color:TEAL}).scale(0.5).move_to([0,-1.75,0]);
  const lb=SurroundingRectangle(lesson,{buff:0.4,color:TEAL});
  scene.play(Create(Arrow(mismatch.get_bottom(),lb.get_top(),{color:GRAY,buff:0.15})),FadeIn(lesson),Create(lb),{run_time:1.5});
  const future=Text("带着适用范围，进入下一次研究",{color:YELLOW}).scale(0.45).move_to([0,-3.0,0]);
  scene.play(FadeIn(future),Indicate(lb),{run_time:1.5});
  scene.wait(0.5);
  return scene;
}

export function build(manim) {
  const {Scene,Text,VGroup,SurroundingRectangle,Arrow,Line,Create,FadeIn,Indicate,BLUE,TEAL,YELLOW,GRAY,WHITE}=manim;
  const scene=new Scene();
  const specs=[["PRAgent","独立重建与检验",-4.1,BLUE],["RunThePaper","保存与共享",0,TEAL],["CyberEinstein","连接历史与新问题",4.1,YELLOW]];
  const groups=specs.map(([name,role,x,color])=>{
    const t=Text(name,{color}).scale_to_fit_width(2.8).move_to([x,1.0,0]);
    const box=SurroundingRectangle(t,{buff:0.35,color});
    const r=Text(role,{color:WHITE}).scale(0.42).move_to([x,-0.4,0]);
    return VGroup(box,t,r);
  });
  for(const g of groups)scene.play(FadeIn(g),{run_time:1.3});
  for(let i=0;i<2;i++)scene.play(Create(Arrow(groups[i].get_right(),groups[i+1].get_left(),{color:GRAY,buff:0.18})),{run_time:1});
  scene.wait(1);
  const a=Line([4.1,-1.2,0],[4.1,-2.2,0],{color:TEAL});
  const b=Arrow([4.1,-2.2,0],[-4.1,-2.2,0],{color:TEAL,buff:0});
  const c=Arrow([-4.1,-2.2,0],[-4.1,-1.2,0],{color:TEAL,buff:0});
  const experience=Text("让新证据和失败经验，回到下一次研究",{color:TEAL}).scale(0.45).move_to([0,-2.85,0]);
  scene.play(Create(a),Create(b),Create(c),FadeIn(experience),{run_time:2});
  const status=Text("正在建设的研究路径",{color:GRAY}).scale(0.38).move_to([0,2.8,0]);
  scene.play(FadeIn(status),{run_time:1});
  scene.wait(0.5);
  return scene;
}

export function build(manim) {
  const {Scene,Text,Graph,Arrow,Line,Create,FadeIn,FadeOut,Indicate,BLUE,TEAL,YELLOW,RED,GRAY,WHITE}=manim;
  const scene=new Scene();
  const pos={p1:[-4.6,1.4,0],p2:[-4.6,-0.8,0],m:[-2.5,0.3,0],q:[0.0,0.3,0],h1:[2.4,1.6,0],h2:[2.4,-1.0,0],r1:[4.9,1.6,0],r2:[4.9,-1.0,0]};
  const pairs=[["p1","m"],["p2","m"],["m","q"],["q","h1"],["q","h2"],["h1","r1"],["h2","r2"]];
  const g=Graph(Object.keys(pos),pairs,{layout:pos,labels:false});
  for(const id of Object.keys(pos))g.get_vertex(id).set_color(id==="q"?YELLOW:id==="r2"?RED:id==="r1"?TEAL:BLUE);
  const past=Text("已有方法与证据",{color:BLUE}).scale(0.4).move_to([-3.8,-2.0,0]);
  scene.play(FadeIn(past),FadeIn(g.get_vertex("p1")),FadeIn(g.get_vertex("p2")),FadeIn(g.get_vertex("m")),Create(g.get_edge("p1","m")),Create(g.get_edge("p2","m")),{run_time:2});
  const qt=Text("一个未解决问题",{color:YELLOW}).scale(0.45).move_to([0,2.7,0]);
  scene.play(FadeIn(g.get_vertex("q")),Create(g.get_edge("m","q")),FadeIn(qt),{run_time:1.5});
  for(const id of ["h1","h2"])scene.play(FadeIn(g.get_vertex(id)),Create(g.get_edge("q",id)),{run_time:0.8});
  const test=Text("提出可检验的假设",{color:WHITE}).scale(0.4).move_to([0,-2.0,0]);
  scene.play(FadeIn(test),{run_time:1});
  for(const n of [["h1","r1"],["h2","r2"]])scene.play(FadeIn(g.get_vertex(n[1])),Create(g.get_edge(n[0],n[1])),{run_time:0.8});
  const supported=Text("获得支持",{color:TEAL}).scale(0.38).move_to([4.9,2.4,0]);
  const excluded=Text("解释被排除",{color:RED}).scale(0.38).move_to([4.9,-1.8,0]);
  scene.play(FadeIn(supported),FadeIn(excluded),{run_time:1.5});
  const scrutiny=Text("保留证据与局限 · 接受独立检查",{color:TEAL}).scale(0.45).move_to([0,-3.0,0]);
  scene.play(FadeIn(scrutiny),{run_time:1});
  scene.wait(0.5);
  return scene;
}
